import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

convtranspose3d_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor convtranspose3d_k3s1_forward(torch::Tensor x,
                                           torch::Tensor w,
                                           c10::optional<torch::Tensor> b);
"""

convtranspose3d_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled ConvTranspose3d for the tested configuration:
//   kernel_size = 3, stride = 1, padding = 0, output_padding = 0,
//   dilation = 1, groups = 1, dtype = float32.
// Each CTA computes an 8x8x8 output spatial tile for 8 output channels.
// Input halo per input-channel chunk is (8+3-1)^3 = 10^3 and is staged in smem.
template <typename T>
__global__ __launch_bounds__(256) void convtranspose3d_k3s1_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int CI, int CO,
    int D, int H, int Wid,
    int Dout, int Hout, int Wout)
{
  constexpr int Threads  = 256;
  constexpr int TD = 8;
  constexpr int TH = 8;
  constexpr int TW = 8;
  constexpr int K  = 3;
  constexpr int HD = TD + K - 1; // 10
  constexpr int HH = TH + K - 1; // 10
  constexpr int HW = TW + K - 1; // 10
  constexpr int CI_CHUNK = 2;
  constexpr int CO_TILE  = 4;
  constexpr int PVec     = 2;
  constexpr int PTile    = Threads * PVec; // 512 = 8^3

  const int tid = threadIdx.x;

  const int n      = blockIdx.z;
  const int co_t   = blockIdx.y;
  const int co0    = co_t * CO_TILE;

  const int ntd = (Dout + TD - 1) / TD;
  const int nth = (Hout + TH - 1) / TH;
  const int ntw = (Wout + TW - 1) / TW;

  int bx = blockIdx.x;
  const int td = bx % ntd; bx /= ntd;
  const int th = bx % nth; bx /= nth;
  const int tw = bx;

  const int d0 = td * TD;
  const int h0 = th * TH;
  const int w0 = tw * TW;

  const int64_t sXn = (int64_t)CI * D * H * Wid;
  const int64_t sXc = (int64_t)D * H * Wid;
  const int64_t sXh = (int64_t)H * Wid;
  const int64_t sXw = (int64_t)Wid;

  const int64_t sYn = (int64_t)CO * Dout * Hout * Wout;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYh = (int64_t)Hout * Wout;
  const int64_t sYw = (int64_t)Wout;

  const int64_t sWci = (int64_t)CO * K * K * K;
  const int64_t sWco = (int64_t)K * K * K;
  const int64_t sWkd = (int64_t)K * K;
  const int64_t sWkh = (int64_t)K;

  Tensor mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(CI, D, H, Wid),
      make_stride(sXc, sXh, sXw, Int<1>{})
  );

  Tensor mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(CO, Dout, Hout, Wout),
      make_stride(sYc, sYh, sYw, Int<1>{})
  );

  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(CI, CO, Int<K>{}, Int<K>{}, Int<K>{}),
      make_stride(sWci, sWco, sWkd, sWkh, Int<1>{})
  );

  __shared__ T sX_raw[CI_CHUNK * HD * HH * HW];
  __shared__ T sW_raw[CI_CHUNK * CO_TILE * K * K * K];

  Tensor sX = make_tensor(
      make_smem_ptr(sX_raw),
      make_shape(Int<CI_CHUNK>{}, Int<HD>{}, Int<HH>{}, Int<HW>{}),
      make_stride(Int<HD * HH * HW>{}, Int<HH * HW>{}, Int<HW>{}, Int<1>{})
  );

  Tensor sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<CI_CHUNK>{}, Int<CO_TILE>{}, Int<K>{}, Int<K>{}, Int<K>{}),
      make_stride(Int<CO_TILE * K * K * K>{}, Int<K * K * K>{}, Int<K * K>{}, Int<K>{}, Int<1>{})
  );

  int   p_idx[PVec];
  int   ld[PVec], lh[PVec], lw[PVec];
  bool  pvalid[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = tid + i * Threads;
    p_idx[i] = p;

    int l_d = p / (TH * TW);
    int rem = p - l_d * (TH * TW);
    int l_h = rem / TW;
    int l_w = rem - l_h * TW;

    ld[i] = l_d;
    lh[i] = l_h;
    lw[i] = l_w;

    int od = d0 + l_d;
    int oh = h0 + l_h;
    int ow = w0 + l_w;
    pvalid[i] = (p < PTile) && (od < Dout) && (oh < Hout) && (ow < Wout);
  }

  float acc[CO_TILE][PVec];
  #pragma unroll
  for (int co = 0; co < CO_TILE; ++co) {
    int gco = co0 + co;
    float bval = 0.0f;
    if (B != nullptr && gco < CO) {
      bval = (float)B[gco];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[co][i] = bval;
    }
  }

  const int in_d0 = d0 - (K - 1);
  const int in_h0 = h0 - (K - 1);
  const int in_w0 = w0 - (K - 1);

  for (int ci0 = 0; ci0 < CI; ci0 += CI_CHUNK) {
    // Cooperative load of the input halo for CI_CHUNK input channels.
    constexpr int X_ELEMS = CI_CHUNK * HD * HH * HW;
    for (int idx = tid; idx < X_ELEMS; idx += Threads) {
      int ci = idx / (HD * HH * HW);
      int rem = idx - ci * (HD * HH * HW);
      int hd = rem / (HH * HW);
      rem -= hd * (HH * HW);
      int hh = rem / HW;
      int hw = rem - hh * HW;

      int gci = ci0 + ci;
      int id  = in_d0 + hd;
      int ih  = in_h0 + hh;
      int iw  = in_w0 + hw;

      T v = T(0);
      if (gci < CI &&
          (unsigned)id < (unsigned)D &&
          (unsigned)ih < (unsigned)H &&
          (unsigned)iw < (unsigned)Wid) {
        v = mX(gci, id, ih, iw);
      }
      sX(ci, hd, hh, hw) = v;
    }

    // Cooperative load of the transposed-conv weights for this channel tile.
    constexpr int W_ELEMS = CI_CHUNK * CO_TILE * K * K * K;
    for (int idx = tid; idx < W_ELEMS; idx += Threads) {
      int ci = idx / (CO_TILE * K * K * K);
      int rem = idx - ci * (CO_TILE * K * K * K);
      int co = rem / (K * K * K);
      rem -= co * (K * K * K);
      int kd = rem / (K * K);
      rem -= kd * (K * K);
      int kh = rem / K;
      int kw = rem - kh * K;

      int gci = ci0 + ci;
      int gco = co0 + co;
      T v = T(0);
      if (gci < CI && gco < CO) {
        v = mW(gci, gco, kd, kh, kw);
      }
      sW(ci, co, kd, kh, kw) = v;
    }

    __syncthreads();

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (!pvalid[i]) continue;

      #pragma unroll
      for (int kd = 0; kd < K; ++kd) {
        int sd = ld[i] + (K - 1) - kd;
        #pragma unroll
        for (int kh = 0; kh < K; ++kh) {
          int sh = lh[i] + (K - 1) - kh;
          #pragma unroll
          for (int kw = 0; kw < K; ++kw) {
            int sw = lw[i] + (K - 1) - kw;

            #pragma unroll
            for (int ci = 0; ci < CI_CHUNK; ++ci) {
              float xv = (float)sX(ci, sd, sh, sw);
              #pragma unroll
              for (int co = 0; co < CO_TILE; ++co) {
                acc[co][i] += xv * (float)sW(ci, co, kd, kh, kw);
              }
            }
          }
        }
      }
    }

    __syncthreads();
  }

  #pragma unroll
  for (int co = 0; co < CO_TILE; ++co) {
    int gco = co0 + co;
    if (gco >= CO) continue;

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (!pvalid[i]) continue;
      int od = d0 + ld[i];
      int oh = h0 + lh[i];
      int ow = w0 + lw[i];
      mY(gco, od, oh, ow) = static_cast<T>(acc[co][i]);
    }
  }
}

torch::Tensor convtranspose3d_k3s1_forward(torch::Tensor x,
                                           torch::Tensor w,
                                           c10::optional<torch::Tensor> b) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) {
    TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  }

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) {
    TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  }

  TORCH_CHECK(x.dim() == 5, "x must be [N, CI, D, H, W]");
  TORCH_CHECK(w.dim() == 5, "w must be [CI, CO, KD, KH, KW] for ConvTranspose3d groups=1");

  const int64_t N   = x.size(0);
  const int64_t CI  = x.size(1);
  const int64_t D   = x.size(2);
  const int64_t H   = x.size(3);
  const int64_t Wid = x.size(4);

  TORCH_CHECK(w.size(0) == CI, "w.size(0) must equal in_channels");
  const int64_t CO = w.size(1);
  TORCH_CHECK(w.size(2) == 3 && w.size(3) == 3 && w.size(4) == 3,
              "custom CUTE kernel currently implements kernel_size = 3");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == CO, "bias must be [out_channels]");
    b_ptr = b_c.data_ptr<float>();
  }

  // stride=1, padding=0, dilation=1, output_padding=0, kernel=3
  const int64_t Dout = D + 2;
  const int64_t Hout = H + 2;
  const int64_t Wout = Wid + 2;

  auto y = torch::empty({N, CO, Dout, Hout, Wout}, x.options());

  constexpr int Threads = 256;
  constexpr int TD = 8;
  constexpr int TH = 8;
  constexpr int TW = 8;
  constexpr int CO_TILE = 4;

  const int64_t ntd = (Dout + TD - 1) / TD;
  const int64_t nth = (Hout + TH - 1) / TH;
  const int64_t ntw = (Wout + TW - 1) / TW;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)(ntd * nth * ntw),
      (unsigned)((CO + CO_TILE - 1) / CO_TILE),
      (unsigned)N
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  convtranspose3d_k3s1_kernel<float><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)CI, (int)CO,
      (int)D, (int)H, (int)Wid,
      (int)Dout, (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "convtranspose3d_k3s1_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

convtranspose3d_ext = load_inline(
    name="cute_convtranspose3d_k3s1_ext",
    cpp_sources=convtranspose3d_cpp_decl,
    cuda_sources=convtranspose3d_cuda_src,
    functions=["convtranspose3d_k3s1_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    ConvTranspose3d implemented with one custom cooperative-tiled CUTE/CUDA kernel.
    Optimized for the provided configuration: square 3x3x3 kernel, stride=1,
    padding=0, output_padding=0, dilation=1, groups=1.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.dilation = dilation
        self.groups = int(groups)
        self.use_bias = bool(bias)

        # Keep the same parameter names/initialization as the reference module.
        self.conv_transpose3d = nn.ConvTranspose3d(
            self.in_channels,
            self.out_channels,
            (self.kernel_size, self.kernel_size, self.kernel_size),
            stride=stride,
            padding=padding,
            output_padding=output_padding,
            dilation=dilation,
            groups=groups,
            bias=bias,
        )

        self._ext = convtranspose3d_ext

        # This single-kernel fast path implements the exact tested case.
        self._supported = (
            self.kernel_size == 3 and
            self.stride == 1 and
            self.padding == 0 and
            self.output_padding == 0 and
            self.dilation == 1 and
            self.groups == 1
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not self._supported:
            raise ValueError(
                "ModelNew custom CUTE kernel supports only kernel_size=3, stride=1, "
                "padding=0, output_padding=0, dilation=1, groups=1."
            )

        bias = self.conv_transpose3d.bias if self.conv_transpose3d.bias is not None else None
        return self._ext.convtranspose3d_k3s1_forward(
            x,
            self.conv_transpose3d.weight,
            bias,
        )

